#![allow(dead_code,unused_imports)]
include!("prefix.rs");
include!("fast_sim.rs");
include!("tri.rs");
use std::{fs,path::Path,io::BufWriter,time::Instant};
const DEFAULT_ZSTD_LEVEL:i32=3;
fn main(){abstract_tests();let args:Vec<_>=std::env::args().collect();let ops=load_ops(&args[1]).unwrap();let(nq,nb,_,regs)=analyze_ops(ops.iter());let p=Compact::compile(&ops);let mut queries=Vec::new();if args.len()>3{let csv=fs::read_to_string(&args[3]).unwrap();let mut compact=0;let mut sites=std::collections::HashMap::new();for(site,o)in ops.iter().enumerate(){if !matches!(o.kind,OperationType::Register|OperationType::AppendToRegister|OperationType::DebugPrint){sites.insert(site,compact);compact+=1;}}let mut lines=csv.lines();let header:Vec<_>=lines.next().unwrap().split(',').collect();for line in lines{let f:Vec<_>=line.split(',').collect();let field=|name:&str|f[header.iter().position(|x|*x==name).unwrap()];let site=field("site").parse::<usize>().unwrap();let o=&ops[site];assert_eq!(o.kind,OperationType::CCX);assert_eq!(o.q_control1.0,field("c1").parse::<u64>().unwrap());assert_eq!(o.q_control2.0,field("c2").parse::<u64>().unwrap());let deleted=field("action")=="del";queries.push(CutQuery{site:sites[&site],deleted,survivor:if deleted{0}else{field("survivor").parse().unwrap()},removed:if deleted{0}else{field("removed_control").parse().unwrap()}});}assert_eq!(queries.len(),144);queries.sort_by_key(|q|q.site);}let rows=fs::read_to_string(&args[2]).unwrap();let(mut bad,mut good)=(Vec::new(),Vec::new());
 for row in rows.lines().skip(1){let f:Vec<_>=row.split('\t').collect();let v=|i|U256::from_str_radix(f[i],16).unwrap();let x=([v(4),v(5),v(6),v(7)],[v(8),v(9)],f[10]=="1");if x.2&&bad.len()<128{bad.push(x);}else if !x.2&&good.len()<128{good.push(x);}if bad.len()==128&&good.len()==128{break;}}
 let inputs:Vec<_>=bad.into_iter().chain(good).collect();let(mut certified,mut known,mut outputs)=(0,0u64,0u64);let start=Instant::now();
 for(batch,chunk)in inputs.chunks(64).enumerate(){let mut tri=TriSim::new(nq as usize,nb as usize);for(lane,(values,_,_))in chunk.iter().enumerate(){for(r,v)in regs[..4].iter().zip(values){tri.set(r,*v,lane);}}
 let q0=tri.q.iter().map(|x|x.v).collect::<Vec<_>>();let b0=tri.b.iter().map(|x|x.v).collect::<Vec<_>>();let t=Instant::now();let possible=tri.apply(&p,&queries);let elapsed=t.elapsed().as_secs_f64();let active=if chunk.len()==64{u64::MAX}else{(1u64<<chunk.len())-1};let inactive=(!possible&active).count_ones();
 let mut h=Shake256::default();h.update(b"rng-free-abstract-fixture-v1");h.update(&(batch as u64).to_le_bytes());let mut rng=h.finalize_xof();let mut real=Simulator::new(nq as usize,nb as usize,&mut rng);real.qubits.copy_from_slice(&q0);real.bits.copy_from_slice(&b0);real.apply_iter(ops.iter());
 for(i,(x,v))in tri.q.iter().zip(&real.qubits).enumerate(){assert!(x.contains(*v),"qubit containment batch={batch} wire={i}");}for(i,(x,v))in tri.b.iter().zip(&real.bits).enumerate(){assert!(x.contains(*v),"bit containment batch={batch} wire={i}");}
 let mut cert=0;let mut realbad=0;let mut bknown=0;for(lane,(_,expected,_))in chunk.iter().enumerate(){let mut wrong=false;let mut actual=false;for(reg,value)in regs[..2].iter().zip(expected){for(i,w)in reg.iter().enumerate(){let(x,v)=match w{QubitOrBit::Qubit(id)=>(tri.q[id.0 as usize],real.qubits[id.0 as usize]),QubitOrBit::Bit(id)=>(tri.b[id.0 as usize],real.bits[id.0 as usize])};let bit=1u64<<lane;let want=(value.bit(i)as u64)<<lane;wrong|=((x.v^want)&!x.u&bit)!=0;actual|=((v^want)&bit)!=0;bknown+=u64::from(x.u&bit==0);outputs+=1;}}if wrong{assert!(actual,"false certificate");cert+=1;}realbad+=usize::from(actual);}
 certified+=cert;known+=bknown;println!("TRI_BATCH batch={batch} inputs={} reference_wrong={realbad} certified={cert} known_output_bits={bknown} all_cuts_inactive={inactive} cut_queries={} abstract_seconds={elapsed:.6} full_state_containment=true",chunk.len(),queries.len());}
 println!("TRI_DONE inputs={} certified={certified} known_output_bits={known} total_output_bits={outputs} wall_seconds={:.6} status=RESEARCH_ONLY",inputs.len(),start.elapsed().as_secs_f64());}
